CREATE OR REPLACE FUNCTION public.enforce_official_affiliate_license() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.license_status='verified' AND NOT public.official_license_exists(NEW.license_number) THEN RAISE EXCEPTION 'מספר הרישיון אינו תקף או אינו מופיע בפנקס המתווכים המורשים'; END IF; RETURN NEW; END $$;
CREATE TRIGGER enforce_official_affiliate_license BEFORE INSERT OR UPDATE ON public.affiliate_profiles FOR EACH ROW EXECUTE FUNCTION public.enforce_official_affiliate_license();
CREATE OR REPLACE FUNCTION public.submit_affiliate_license(_license_number text,_holder_name text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF; IF NOT public.official_license_exists(_license_number) OR NOT EXISTS(SELECT 1 FROM public.broker_license_verifications WHERE user_id=uid AND license_number=_license_number AND verified_at>now()-interval '24 hours') THEN RAISE EXCEPTION 'מספר הרישיון אינו תקף או אינו מופיע בפנקס המתווכים המורשים'; END IF; INSERT INTO public.affiliate_profiles(user_id,license_number,license_holder_name,license_status,license_submitted_at) VALUES(uid,_license_number,(SELECT holder_name FROM public.official_brokers_registry WHERE license_number=_license_number),'pending',now()) ON CONFLICT(user_id) DO UPDATE SET license_number=excluded.license_number,license_holder_name=excluded.license_holder_name,license_status=CASE WHEN public.affiliate_profiles.license_status='verified' AND public.affiliate_profiles.license_number=excluded.license_number THEN 'verified' ELSE 'pending' END,license_submitted_at=now(); RETURN jsonb_build_object('ok',true,'status','verified'); END $$;
CREATE OR REPLACE FUNCTION public.get_workspace_owner_roles(_owner uuid) RETURNS text[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN auth.uid()=_owner OR public.has_role(auth.uid(),'super_admin') OR EXISTS(SELECT 1 FROM public.workspace_memberships m WHERE m.workspace_owner_id=_owner AND m.user_id=auth.uid()) THEN coalesce((SELECT array_agg(role::text) FROM public.user_roles WHERE user_id=_owner AND (role NOT IN ('agent','lead_agent','managing_broker','junior_agent') OR public.has_verified_broker_license(_owner))),'{}'::text[]) ELSE '{}'::text[] END $$;